perl << 'PERL'
use strict;
use warnings;
use File::Find;

my $repo = "/bench/repo";

my @entities = qw(
  Attachment
  AuthenticationConfigState
  IdentityProvider
  Inbox
  InstanceSetting
  Memo
  MemoRelation
  MemoShare
  Reaction
  User
  UserIdentity
  UserSetting
);

sub is_store_layer {
  my ($path) = @_;
  my $rel = $path;
  $rel =~ s/^\Q$repo\E\/?//;
  return $rel =~ /^store(\/|$)/;
}

my @go_files;
find({
  wanted => sub {
    return unless -f && /\.go$/;
    return if $File::Find::name =~ /\/\.git\//;
    return if is_store_layer($File::Find::name);
    push @go_files, $File::Find::name;
  },
  no_chdir => 1,
}, $repo);

print "Files outside store layer: " . scalar(@go_files) . "\n";

my %pkgset;
for my $f (@go_files) {
  my $d = $f;
  $d =~ s/\/[^\/]+$//;
  $pkgset{$d} = 1;
}
print "Packages outside store:\n";
for my $p (sort keys %pkgset) {
  my $rel = $p;
  $rel =~ s/^\Q$repo\E\/?//;
  print "  $rel\n";
}

sub count_pattern {
  my ($pat) = @_;
  my %pkgs;
  my @files;
  for my $f (@go_files) {
    open my $fh, "<", $f or die $!;
    local $/;
    my $text = <$fh>;
    close $fh;
    if ($text =~ /$pat/) {
      my $d = $f;
      $d =~ s/\/[^\/]+$//;
      $pkgs{$d} = 1;
      my $rel = $f;
      $rel =~ s/^\Q$repo\E\/?//;
      push @files, $rel;
    }
  }
  return (\%pkgs, \@files);
}

print "\n======= Exact entity type: store.Type (word boundary) =======\n";
my @results;
for my $e (@entities) {
  my $pat = qr/\bstore\.\Q$e\E\b/;
  my ($pkgs, $files) = count_pattern($pat);
  my @prel = map { my $r = $_; $r =~ s/^\Q$repo\E\/?//; $r } sort keys %$pkgs;
  push @results, [scalar(keys %$pkgs), $e, \@prel, $files];
}
@results = sort { $b->[0] <=> $a->[0] || $a->[1] cmp $b->[1] } @results;
for my $r (@results) {
  my ($n, $e, $pkgs, $files) = @$r;
  print "\n$e: $n packages, " . scalar(@$files) . " files\n";
  print "  pkgs: " . join(", ", @$pkgs) . "\n";
}

print "\n======= Entity + Find/Update/Delete =======\n";
my @results2;
for my $e (@entities) {
  my $pat = qr/\bstore\.(?:Find|Update|Delete|Create)?\Q$e\E\b/;
  my ($pkgs, $files) = count_pattern($pat);
  my @prel = map { my $r = $_; $r =~ s/^\Q$repo\E\/?//; $r } sort keys %$pkgs;
  push @results2, [scalar(keys %$pkgs), $e, \@prel];
}
@results2 = sort { $b->[0] <=> $a->[0] || $a->[1] cmp $b->[1] } @results2;
for my $r (@results2) {
  my ($n, $e, $pkgs) = @$r;
  print "$e: $n packages -> " . join(", ", @$pkgs) . "\n";
}
PERL

